const fs=require('node:fs');const path=require('node:path');const crypto=require('node:crypto');const assert=require('node:assert/strict');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const START='function setProtocoloGNoStoreHeaders(res) {';
const END="app.get('/protocolo-g', serveProtocoloGByDevice);";
function protectedCore(bytes){const s=bytes.toString('utf8').replace(/^\uFEFF/,'');const a=s.indexOf(START),b=s.indexOf(END,a);assert(a>=0&&b>a,'PROTECTED_ROUTE_MARKERS');return s.slice(a,b+END.length);}
